INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1308, 12, 2074, '3.5.4', '', 'active', '2026-06-03 12:23:19.373068', '2026-06-03 12:23:19.372812', 'CP-3-5-4-001', '3.5.4 进场的胶合模板除应具有出厂质量合格证外，还应保证外观及尺寸合格。', '["胶合模板", "出厂质量合格证", "外观", "尺寸"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1488, 12, 2127, '6.1.1', '1 应审查模板结构设计与施工说明书中的荷载、计算方法、节点构造和安全措施，设计审批手续应齐全。
2 应进行全面的安全技术交底，操作班组应熟悉设计与施工说明书，并应做好模板安装作业的分工准备。采用爬模、飞模、隧道模等特殊模板施工时，所有参加作业人员必须经过专门技术培训，考核合格后方可上岗。
3 应对模板和配件进行挑选、检测，不合格者应剔除，并应运至工地指定地点堆放。
4 备齐操作所需的一切安全防护设施和器具。', 'active', '2026-06-03 12:28:31.948983', '2026-06-03 12:28:31.947273', 'CP-6-1-1-003', '采用爬模、飞模、隧道模等特殊模板施工时，所有参加作业人员必须经过专门技术培训，考核合格后方可上岗。', '["爬模", "飞模", "隧道模", "特殊模板", "作业人员", "专门技术培训"]', 0.95);
