INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (43, 6, 1319, '3.1.4', '焊接的承重结构以及重要的非焊接承重结构采用的钢材还应具有冷弯试验的合格保证。', 'active', '2026-06-02 03:46:27.139331', '2026-06-02 03:46:27.13778', 'CP-3-1-4-001', '3.1.4 承重结构采用的钢材应具有抗拉强度、伸长率、屈服强度和硫、磷含量的合格保证，对焊接结构尚应具有碳含量的合格保证。', '["承重结构", "钢材", "抗拉强度", "伸长率", "屈服强度", "硫", "磷含量", "焊接结构", "碳含量"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (44, 6, 1319, '3.1.4', '焊接的承重结构以及重要的非焊接承重结构采用的钢材还应具有冷弯试验的合格保证。', 'active', '2026-06-02 03:46:27.141399', '2026-06-02 03:46:27.13778', 'CP-3-1-4-002', '焊接的承重结构以及重要的非焊接承重结构采用的钢材还应具有冷弯试验的合格保证。', '["焊接的承重结构", "重要的非焊接承重结构", "钢材", "冷弯试验"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (55, 6, 1325, '3.2.4', '1 普通螺栓除应符合本规范第 3.1.2 条第 6 款的规定外，其机械性能还应符合现行国家标准《紧固件机械性能螺栓、螺钉和螺柱》GB/T 3098.1 的规定。
2 连接薄钢板或其他金属板采用的自攻螺钉应符合现行国家标准《自钻自攻螺钉》GB/T 15856.1～4、GB/T 3098.11 或《自攻螺栓》GB/T 5282～5285 的规定。', 'active', '2026-06-02 03:46:49.085629', '2026-06-02 03:46:49.085402', 'CP-3-2-4-001', '3.2.4 连接件及连接材料应符合下列规定：1 普通螺栓除应符合本规范第 3.1.2 条第 6 款的规定外，其机械性能还应符合现行国家标准《紧固件机械性能螺栓、螺钉和螺柱》GB/T 3098.1 的规定。', '["普通螺栓", "机械性能", "紧固件机械性能螺栓、螺钉和螺柱", "GB/T 3098.1"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (56, 6, 1325, '3.2.4', '1 普通螺栓除应符合本规范第 3.1.2 条第 6 款的规定外，其机械性能还应符合现行国家标准《紧固件机械性能螺栓、螺钉和螺柱》GB/T 3098.1 的规定。
2 连接薄钢板或其他金属板采用的自攻螺钉应符合现行国家标准《自钻自攻螺钉》GB/T 15856.1～4、GB/T 3098.11 或《自攻螺栓》GB/T 5282～5285 的规定。', 'active', '2026-06-02 03:46:49.086485', '2026-06-02 03:46:49.085402', 'CP-3-2-4-002', '2 连接薄钢板或其他金属板采用的自攻螺钉应符合现行国家标准《自钻自攻螺钉》GB/T 15856.1～4、GB/T 3098.11 或《自攻螺栓》GB/T 5282～5285 的规定。', '["连接薄钢板", "其他金属板", "自攻螺钉", "自钻自攻螺钉", "GB/T 15856.1～4", "GB/T 3098.11", "自攻螺栓", "GB/T 5282～5285"]', 0.95);
