INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (74, 6, 1334, '3.3.7', '', 'active', '2026-06-02 03:47:25.603656', '2026-06-02 03:47:25.603408', 'CP-3-3-7-001', '3.3.7 当需要对模板结构或构件木材的强度进行测试验证时，应按现行国家标准《木结构设计规范》GB 50005 的检验标准进行。', '["模板结构", "构件木材", "强度", "检验标准", "《木结构设计规范》GB 50005"]', 0.95);
