INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (92, 6, 1338, '3.4.2', '<div style="text-align: center;">表 3.4.2 铝合金型材的机械性能</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>牌号</td><td style=''text-align: center; word-wrap: break-word;''>材料状态</td><td style=''text-align: center; word-wrap: break-word;''>壁厚 (mm)</td><td style=''text-align: center; word-wrap: break-word;''>抗拉极限强度  $ \sigma_{b} $ (N/mm²)</td><td style=''text-align: center; word-wrap: break-word;''>屈服强度  $ \sigma_{0.2} $ (N/mm²)</td><td style=''text-align: center; word-wrap: break-word;''>伸长率  $ \delta $ (%)</td><td style=''text-align: center; word-wrap: break-word;''>弹性模量  $ E_{c} $ (N/mm²)</td></tr><tr><td rowspan="2">LD₂</td><td style=''text-align: center; word-wrap: break-word;''>C₂</td><td rowspan="2">所有尺寸</td><td style=''text-align: center; word-wrap: break-word;''>≥180</td><td style=''text-align: center; word-wrap: break-word;''>—</td><td style=''text-align: center; word-wrap: break-word;''>≥14</td><td rowspan="4">1.83×10⁵</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C₃</td><td style=''text-align: center; word-wrap: break-word;''>≥280</td><td style=''text-align: center; word-wrap: break-word;''>≥210</td><td style=''text-align: center; word-wrap: break-word;''>≥12</td></tr><tr><td rowspan="2">LY₁₁</td><td style=''text-align: center; word-wrap: break-word;''>C₂</td><td style=''text-align: center; word-wrap: break-word;''>≤10.0</td><td style=''text-align: center; word-wrap: break-word;''>≥360</td><td style=''text-align: center; word-wrap: break-word;''>≥220</td><td style=''text-align: center; word-wrap: break-word;''>≥12</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>C₃</td><td style=''text-align: center; word-wrap: break-word;''>10.1～20.0</td><td style=''text-align: center; word-wrap: break-word;''>≥380</td><td style=''text-align: center; word-wrap: break-word;''>≥230</td><td style=''text-align: center; word-wrap: break-word;''>≥12</td></tr></table>
<div style="text-align: center;">续表 3.4.2</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>牌号</td><td style=''text-align: center; word-wrap: break-word;''>材料状态</td><td style=''text-align: center; word-wrap: break-word;''>壁厚（mm）</td><td style=''text-align: center; word-wrap: break-word;''>抗拉极限强度 $ \sigma_{b} $（N/mm²）</td><td style=''text-align: center; word-wrap: break-word;''>屈服强度 $ \sigma_{0.2} $（N/mm²）</td><td style=''text-align: center; word-wrap: break-word;''>伸长率 $ \delta $（%）</td><td style=''text-align: center; word-wrap: break-word;''>弹性模量 $ E_{c} $（N/mm²）</td></tr><tr><td rowspan="3">LY12</td><td rowspan="3">Cz</td><td style=''text-align: center; word-wrap: break-word;''>&lt;5.0</td><td style=''text-align: center; word-wrap: break-word;''>≥400</td><td style=''text-align: center; word-wrap: break-word;''>≥300</td><td style=''text-align: center; word-wrap: break-word;''>≥10</td><td rowspan="3">2.14×10⁵</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>5.1～10.0</td><td style=''text-align: center; word-wrap: break-word;''>≥420</td><td style=''text-align: center; word-wrap: break-word;''>≥300</td><td style=''text-align: center; word-wrap: break-word;''>≥10</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>10.1～20.0</td><td style=''text-align: center; word-wrap: break-word;''>≥430</td><td style=''text-align: center; word-wrap: break-word;''>≥310</td><td style=''text-align: center; word-wrap: break-word;''>≥10</td></tr><tr><td rowspan="2">LC4</td><td rowspan="2">Cs</td><td style=''text-align: center; word-wrap: break-word;''>≤10.0</td><td style=''text-align: center; word-wrap: break-word;''>≥510</td><td style=''text-align: center; word-wrap: break-word;''>≥440</td><td style=''text-align: center; word-wrap: break-word;''>≥6</td><td rowspan="2">2.14×10⁵</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>10.1～20.0</td><td style=''text-align: center; word-wrap: break-word;''>≥540</td><td style=''text-align: center; word-wrap: break-word;''>≥450</td><td style=''text-align: center; word-wrap: break-word;''>≥6</td></tr></table>
注：材料状态代号名称： $ C_{z} $—淬火（自然时效）； $ C_{s} $—淬火（人工时效）。', 'active', '2026-06-02 03:48:05.520586', '2026-06-02 03:48:05.520091', 'CP-3-4-2-001', '牌号LD₂、材料状态C₂、壁厚所有尺寸，抗拉极限强度≥180N/mm²，屈服强度—，伸长率≥14%，弹性模量1.83×10⁵N/mm²', '["铝合金型材", "牌号", "材料状态", "壁厚", "抗拉极限强度", "屈服强度", "伸长率", "弹性模量"]', 0.90);
