INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (171, 6, 1388, '5.2.7', '', 'active', '2026-06-02 06:33:25.105541', '2026-06-02 06:33:25.105251', 'CP-5-2-7-001', '5.2.7 框架和剪力墙的模板、钢筋全部安装完毕后，应验算在本地区规定的风压作用下，整个模板系统的稳定性。其验算方法应将要求的风力与模板系统、钢筋的自重乘以相应荷载分项系数后，求其合力作用线不得超过背风面的柱脚或墙底脚的外边。', '["框架", "剪力墙", "模板", "钢筋", "风压", "模板系统", "荷载分项系数", "合力作用线", "柱脚", "墙底脚"]', 0.95);
