INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (135, 6, 1370, '5.1.1', '', 'active', '2026-06-02 06:31:22.181059', '2026-06-02 06:31:22.180745', 'CP-5-1-1-001', '5.1.1 模板及其支架的设计应根据工程结构形式、荷载大小、地基土类别、施工设备和材料等条件进行。', '["模板", "支架", "工程结构形式", "荷载大小", "地基土类别", "施工设备", "材料"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (145, 6, 1372, '5.1.3', '1 根据混凝土的施工工艺和季节性施工措施，确定其构造和所承受的荷载；
2 绘制配板设计图、支撑设计布置图、细部构造和异形模板大样图；
3 按模板承受荷载的最不利组合对模板进行验算；
4 制定模板安装及拆除的程序和方法；
5 编制模板及配件的规格、数量汇总表和周转使用计划；
6 编制模板施工安全、防火技术措施及设计、施工说明书。', 'active', '2026-06-02 06:31:40.496975', '2026-06-02 06:31:40.49227', 'CP-5-1-3-006', '编制模板施工安全、防火技术措施及设计、施工说明书。', '["模板施工", "安全", "防火技术措施", "设计", "施工说明书"]', 1.00);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (146, 6, 1374, '5.1.5', '', 'active', '2026-06-02 06:31:43.912229', '2026-06-02 06:31:43.911902', 'CP-5-1-5-001', '5.1.5 模板中的木构件设计应符合现行国家标准《木结构设计规范》GB 50005 的规定，', '["木构件", "国家标准", "《木结构设计规范》GB 50005"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (147, 6, 1374, '5.1.5', '', 'active', '2026-06-02 06:31:43.913206', '2026-06-02 06:31:43.911902', 'CP-5-1-5-002', '其中受压立杆应满足计算要求，且其梢径不得小于 80mm。', '["受压立杆", "梢径"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (153, 6, 1376, '5.1.7', '1 连接扣件和钢管立杆底座应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定；
2 承重的支架柱，其荷载应直接作用于立杆的轴线上，严禁承受偏心荷载，并应按单立杆轴心受压计算；钢管的初始弯曲率不得大于1/1000，其壁厚应按实际检查结果计算；
3 当露天支架立柱为群柱架时，高宽比不应大于 5；当高宽比大于 5 时，必须加设抛撑或缆风绳，保证宽度方向的稳定。', 'active', '2026-06-02 06:32:00.076447', '2026-06-02 06:32:00.07621', 'CP-5-1-7-001', '5.1.7 用扣件式钢管脚手架作支架立柱时，应符合下列规定：1 连接扣件和钢管立杆底座应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定；', '["扣件式钢管脚手架", "支架立柱", "连接扣件", "钢管立杆底座"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (154, 6, 1376, '5.1.7', '1 连接扣件和钢管立杆底座应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定；
