INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (115, 6, 1356, '4.2.3', '<div style="text-align: center;">表 4.2.3 荷载分项系数</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>荷载类别</td><td style=''text-align: center; word-wrap: break-word;''>分项系数  $ \gamma_{i} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>模板及支架自重标准值（ $ G_{1k} $）</td><td rowspan="4">永久荷载的分项系数：（1）当其效应对结构不利时：对由可变荷载效应控制的组合，应取1.2；对由永久荷载效应控制的组合，应取1.35；（2）当其效应对结构有利时：一般情况应取1；对结构的倾覆、滑移验算，应取0.9。</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>新浇混凝土自重标准值（ $ G_{2k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>钢筋自重标准值（ $ G_{3k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>新浇混凝土对模板的侧压力标准值（ $ G_{4k} $）</td></tr></table>
<div style="text-align: center;">续表 4.2.3</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>荷载类别</td><td style=''text-align: center; word-wrap: break-word;''>分项系数  $ \gamma_{i} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>施工人员及施工设备荷载标准值（ $ Q_{1k} $）</td><td rowspan="3">可变荷载的分项系数：一般情况下应取1.4；对标准值大于4kN/m²的活荷载应取1.3。</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>振捣混凝土时产生的荷载标准值（ $ Q_{2k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>倾倒混凝土时产生的荷载标准值（ $ Q_{3k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>风荷载（ $ \tau_{w_k} $）</td><td style=''text-align: center; word-wrap: break-word;''>1.4</td></tr></table>', 'active', '2026-06-02 06:30:21.336744', '2026-06-02 06:30:21.331116', 'CP-4-2-3-007', '倾倒混凝土时产生的荷载标准值（ $ Q_{3k} $）可变荷载的分项系数：一般情况下应取1.4；对标准值大于4kN/m²的活荷载应取1.3。', '["倾倒混凝土时产生的荷载标准值", "可变荷载分项系数"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (116, 6, 1356, '4.2.3', '<div style="text-align: center;">表 4.2.3 荷载分项系数</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>荷载类别</td><td style=''text-align: center; word-wrap: break-word;''>分项系数  $ \gamma_{i} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>模板及支架自重标准值（ $ G_{1k} $）</td><td rowspan="4">永久荷载的分项系数：（1）当其效应对结构不利时：对由可变荷载效应控制的组合，应取1.2；对由永久荷载效应控制的组合，应取1.35；（2）当其效应对结构有利时：一般情况应取1；对结构的倾覆、滑移验算，应取0.9。</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>新浇混凝土自重标准值（ $ G_{2k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>钢筋自重标准值（ $ G_{3k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>新浇混凝土对模板的侧压力标准值（ $ G_{4k} $）</td></tr></table>
<div style="text-align: center;">续表 4.2.3</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>荷载类别</td><td style=''text-align: center; word-wrap: break-word;''>分项系数  $ \gamma_{i} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>施工人员及施工设备荷载标准值（ $ Q_{1k} $）</td><td rowspan="3">可变荷载的分项系数：一般情况下应取1.4；对标准值大于4kN/m²的活荷载应取1.3。</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>振捣混凝土时产生的荷载标准值（ $ Q_{2k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>倾倒混凝土时产生的荷载标准值（ $ Q_{3k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>风荷载（ $ \tau_{w_k} $）</td><td style=''text-align: center; word-wrap: break-word;''>1.4</td></tr></table>', 'active', '2026-06-02 06:30:21.337555', '2026-06-02 06:30:21.331116', 'CP-4-2-3-008', '风荷载（ $ 	au_{w_k} $）分项系数应取1.4。', '["风荷载", "分项系数"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (126, 6, 1364, '4.4.1', '1）对结构表面外露的模板，为模板构件计算跨度的1/400；
2 对结构表面隐蔽的模板，为模板构件计算跨度的 1/250；
3 支架的压缩变形或弹性挠度，为相应的结构计算跨度的1/1000。', 'active', '2026-06-02 06:30:59.244157', '2026-06-02 06:30:59.2439', 'CP-4-4-1-001', '4.4.1 当验算模板及其支架的刚度时，其最大变形值不得超过下列容许值：1）对结构表面外露的模板，为模板构件计算跨度的1/400；', '["模板", "支架", "刚度", "最大变形值", "结构表面外露的模板", "模板构件计算跨度"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1315, 12, 2076, '3.5.6', '1 不浸泡，不蒸煮：剪切强度  $ 1.4 \sim 1.8 N/mm^{2} $;
2 室温水浸泡：剪切强度  $ 1.2 \sim 1.8 N/mm^{2} $;
3 沸水煮 24h：剪切强度 1.2～1.8N/mm²；
4 含水率：5%～13%；
5 密度：450～880kg/m³；
6 弹性模量： $ 4.5 \times 10^{3} \sim 11.5 \times 10^{3} N/mm^{2} $。', 'active', '2026-06-03 12:23:45.589613', '2026-06-03 12:23:45.585462', 'CP-3-5-6-007', '6 弹性模量： $ 4.5 \times 10^{3} \sim 11.5 \times 10^{3} N/mm^{2} $。', '["弹性模量"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1333, 12, 2082, '4.1.3', '', 'active', '2026-06-03 12:24:07.54452', '2026-06-03 12:24:07.54429', 'CP-4-1-3-001', '风荷载标准值应按现行国家标准《建筑结构荷载规范》GB 50009－2001（2006年版）中的规定计算，其中基本风压值应按该规范附表D.4中n=10年的规定采用，并取风振系数 $ eta_{z}=1 $。', '["风荷载标准值", "建筑结构荷载规范", "基本风压值", "附表D.4", "风振系数"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (127, 6, 1364, '4.4.1', '1）对结构表面外露的模板，为模板构件计算跨度的1/400；
2 对结构表面隐蔽的模板，为模板构件计算跨度的 1/250；
3 支架的压缩变形或弹性挠度，为相应的结构计算跨度的1/1000。', 'active', '2026-06-02 06:30:59.244905', '2026-06-02 06:30:59.2439', 'CP-4-4-1-002', '2 对结构表面隐蔽的模板，为模板构件计算跨度的 1/250；', '["结构表面隐蔽的模板", "模板构件计算跨度"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (128, 6, 1364, '4.4.1', '1）对结构表面外露的模板，为模板构件计算跨度的1/400；
2 对结构表面隐蔽的模板，为模板构件计算跨度的 1/250；
3 支架的压缩变形或弹性挠度，为相应的结构计算跨度的1/1000。', 'active', '2026-06-02 06:30:59.245515', '2026-06-02 06:30:59.2439', 'CP-4-4-1-003', '3 支架的压缩变形或弹性挠度，为相应的结构计算跨度的1/1000。', '["支架", "压缩变形", "弹性挠度", "结构计算跨度"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (136, 6, 1371, '5.1.2', '1 应具有足够的承载能力、刚度和稳定性，应能可靠地承受新浇混凝土的自重、侧压力和施工过程中所产生的荷载及风荷载。
2 构造应简单，装拆方便，便于钢筋的绑扎、安装和混凝土的浇筑、养护。
3 混凝土梁的施工应采用从跨中向两端对称进行分层浇筑，每层厚度不得大于 400mm。
4 当验算模板及其支架在自重和风荷载作用下的抗倾覆稳定性时，应符合相应材质结构设计规范的规定。', 'active', '2026-06-02 06:31:35.010644', '2026-06-02 06:31:35.010392', 'CP-5-1-2-001', '5.1.2 模板及其支架的设计应符合下列规定：1 应具有足够的承载能力、刚度和稳定性，应能可靠地承受新浇混凝土的自重、侧压力和施工过程中所产生的荷载及风荷载。', '["模板", "支架", "新浇混凝土", "荷载", "风荷载"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (137, 6, 1371, '5.1.2', '1 应具有足够的承载能力、刚度和稳定性，应能可靠地承受新浇混凝土的自重、侧压力和施工过程中所产生的荷载及风荷载。
2 构造应简单，装拆方便，便于钢筋的绑扎、安装和混凝土的浇筑、养护。
3 混凝土梁的施工应采用从跨中向两端对称进行分层浇筑，每层厚度不得大于 400mm。
4 当验算模板及其支架在自重和风荷载作用下的抗倾覆稳定性时，应符合相应材质结构设计规范的规定。', 'active', '2026-06-02 06:31:35.01137', '2026-06-02 06:31:35.010392', 'CP-5-1-2-002', '2 构造应简单，装拆方便，便于钢筋的绑扎、安装和混凝土的浇筑、养护。', '["构造", "钢筋", "混凝土"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1355, 12, 2086, '4.2.3', '<div style="text-align: center;">表 4.2.3 荷载分项系数</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>荷载类别</td><td style=''text-align: center; word-wrap: break-word;''>分项系数  $ \gamma_{i} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>模板及支架自重标准值（ $ G_{1k} $）</td><td rowspan="4">永久荷载的分项系数：（1）当其效应对结构不利时：对由可变荷载效应控制的组合，应取1.2；对由永久荷载效应控制的组合，应取1.35；（2）当其效应对结构有利时：一般情况应取1；对结构的倾覆、滑移验算，应取0.9。</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>新浇混凝土自重标准值（ $ G_{2k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>钢筋自重标准值（ $ G_{3k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>新浇混凝土对模板的侧压力标准值（ $ G_{4k} $）</td></tr></table>
<div style="text-align: center;">续表 4.2.3</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>荷载类别</td><td style=''text-align: center; word-wrap: break-word;''>分项系数  $ \gamma_{i} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>施工人员及施工设备荷载标准值（ $ Q_{1k} $）</td><td rowspan="3">可变荷载的分项系数：一般情况下应取1.4；对标准值大于4kN/m²的活荷载应取1.3。</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>振捣混凝土时产生的荷载标准值（ $ Q_{2k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>倾倒混凝土时产生的荷载标准值（ $ Q_{3k} $）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>风荷载（ $ \tau_{w_k} $）</td><td style=''text-align: center; word-wrap: break-word;''>1.4</td></tr></table>', 'active', '2026-06-03 12:24:52.081738', '2026-06-03 12:24:52.08151', 'CP-4-2-3-001', '4.2.3 荷载分项系数应按表 4.2.3 采用。', '["荷载分项系数"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1489, 12, 2127, '6.1.1', '1 应审查模板结构设计与施工说明书中的荷载、计算方法、节点构造和安全措施，设计审批手续应齐全。
2 应进行全面的安全技术交底，操作班组应熟悉设计与施工说明书，并应做好模板安装作业的分工准备。采用爬模、飞模、隧道模等特殊模板施工时，所有参加作业人员必须经过专门技术培训，考核合格后方可上岗。
3 应对模板和配件进行挑选、检测，不合格者应剔除，并应运至工地指定地点堆放。
4 备齐操作所需的一切安全防护设施和器具。', 'active', '2026-06-03 12:28:31.949622', '2026-06-03 12:28:31.947273', 'CP-6-1-1-004', '3 应对模板和配件进行挑选、检测，不合格者应剔除，并应运至工地指定地点堆放。', '["模板", "配件", "挑选", "检测", "不合格者", "工地指定地点", "堆放"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (255, 6, 1433, '6.4.8', '如需临时堆放少量材料或机具，必须及时取走，且不得超过设计荷载的规定。', 'active', '2026-06-02 06:37:04.689294', '2026-06-02 06:37:04.68896', 'CP-6-4-8-001', '脚手架上不应堆放材料，脚手架上的垃圾应及时清除。', '["脚手架", "材料", "垃圾"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (256, 6, 1433, '6.4.8', '如需临时堆放少量材料或机具，必须及时取走，且不得超过设计荷载的规定。', 'active', '2026-06-02 06:37:04.690366', '2026-06-02 06:37:04.68896', 'CP-6-4-8-002', '如需临时堆放少量材料或机具，必须及时取走，且不得超过设计荷载的规定。', '["材料", "机具", "设计荷载"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (270, 6, 1438, '6.5.3', '', 'active', '2026-06-02 06:37:31.719102', '2026-06-02 06:37:31.71886', 'CP-6-5-3-001', '6.5.3 飞模就位后，应立即在外侧设置防护栏，其高度不得小于 1.2m', '["飞模", "防护栏", "高度"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (271, 6, 1438, '6.5.3', '', 'active', '2026-06-02 06:37:31.720012', '2026-06-02 06:37:31.71886', 'CP-6-5-3-002', '外侧应另加设安全网，同时应设置楼层护栏。', '["安全网", "楼层护栏"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (272, 6, 1438, '6.5.3', '', 'active', '2026-06-02 06:37:31.720714', '2026-06-02 06:37:31.71886', 'CP-6-5-3-003', '并应准确、牢固地搭设出模操作平台。', '["出模操作平台"]', 0.95);
