INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1329, 12, 2075, '3.5.5', '<div style="text-align: center;">表 3.5.5 竹胶合模板技术性能</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">项目</td><td style=''text-align: center; word-wrap: break-word;''>平均值</td><td style=''text-align: center; word-wrap: break-word;''>备注</td></tr><tr><td rowspan="2">静曲强度  $ \sigma $ (N/mm²)</td><td style=''text-align: center; word-wrap: break-word;''>3层</td><td style=''text-align: center; word-wrap: break-word;''>113.30</td><td rowspan="2">$ \sigma = (3PL)/(2bh^{2}) $ 式中 P — 破坏荷载； L ——支座距离（240mm）； b ——试件宽度（20mm）； h ——试件厚度（胶合模板 h=15mm）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>5层</td><td style=''text-align: center; word-wrap: break-word;''>105.50</td></tr><tr><td rowspan="2">弹性模量 E (N/mm²)</td><td style=''text-align: center; word-wrap: break-word;''>3层</td><td style=''text-align: center; word-wrap: break-word;''>10584</td><td rowspan="2">$ E = 4(\Delta PL^{5})/(\Delta fbh^{3}) $ 式中 L、b、h 同上，其中 3 层  $ \Delta P/\Delta f = 211.6 $；5 层  $ \Delta P/\Delta f = 197.7 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>5层</td><td style=''text-align: center; word-wrap: break-word;''>9898</td></tr><tr><td rowspan="2">冲击强度 A (J/cm²)</td><td style=''text-align: center; word-wrap: break-word;''>3层</td><td style=''text-align: center; word-wrap: break-word;''>8.30</td><td rowspan="2">$ A = Q/(b \times h) $ 式中 Q ——折损耗功； b ——试件宽度； h ——试件厚度</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>5层</td><td style=''text-align: center; word-wrap: break-word;''>7.95</td></tr><tr><td rowspan="2">胶合强度  $ \tau $ (N/mm²)</td><td style=''text-align: center; word-wrap: break-word;''>3层</td><td style=''text-align: center; word-wrap: break-word;''>3.52</td><td rowspan="2">$ \tau = P/(b \times l) $ 式中 P ——剪切破坏荷载（N）； b ——剪面宽度（20mm）； l ——切面长度（28mm）</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>5层</td><td style=''text-align: center; word-wrap: break-word;''>5.03</td></tr><tr><td colspan="2">握钉力 M(N/mm)</td><td style=''text-align: center; word-wrap: break-word;''>241.10</td><td style=''text-align: center; word-wrap: break-word;''>$ M = P/h $ 式中 P ——破坏荷载（N）； h ——试件厚度（mm）</td></tr></table>', 'active', '2026-06-03 12:24:02.380362', '2026-06-03 12:24:02.376833', 'CP-3-5-5-006', '冲击强度 A (J/cm²) 5层 7.95 $ A = Q/(b \times h) $ 式中 Q ——折损耗功； b ——试件宽度； h ——试件厚度', '["冲击强度", "A", "5层", "折损耗功", "试件宽度", "试件厚度"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1330, 12, 2075, '3.5.5', '<div style="text-align: center;">表 3.5.5 竹胶合模板技术性能</div>
