INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1490, 12, 2127, '6.1.1', '1 应审查模板结构设计与施工说明书中的荷载、计算方法、节点构造和安全措施，设计审批手续应齐全。
2 应进行全面的安全技术交底，操作班组应熟悉设计与施工说明书，并应做好模板安装作业的分工准备。采用爬模、飞模、隧道模等特殊模板施工时，所有参加作业人员必须经过专门技术培训，考核合格后方可上岗。
3 应对模板和配件进行挑选、检测，不合格者应剔除，并应运至工地指定地点堆放。
4 备齐操作所需的一切安全防护设施和器具。', 'active', '2026-06-03 12:28:31.950275', '2026-06-03 12:28:31.947273', 'CP-6-1-1-005', '4 备齐操作所需的一切安全防护设施和器具。', '["安全防护设施", "器具"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1495, 12, 2133, '6.1.7', '', 'active', '2026-06-03 12:28:45.861846', '2026-06-03 12:28:45.861608', 'CP-6-1-7-001', '6.1.7 除设计图另有规定者外，所有垂直支架柱应保证其垂直。', '["设计图", "垂直支架柱"]', 1.00);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1671, 12, 2188, '7.1.7', '', 'active', '2026-06-03 12:32:53.372572', '2026-06-03 12:32:53.37234', 'CP-7-1-7-001', '模板的拆除工作应设专人指挥。', '["模板", "拆除工作", "专人"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (157, 6, 1378, '5.1.9', '1 水平支承如倾斜或由倾斜的托板支承以及偏心荷载情况存在时；
2 梁由多杆件组成；
3 当梁的高宽比大于 2.5 时，水平支承梁的底面严禁支承在 50mm 宽的单托板面上；
4 水平支承梁的高宽比大于 2.5 时，应避免承受集中荷载。', 'active', '2026-06-02 06:32:14.471098', '2026-06-02 06:32:14.470853', 'CP-5-1-9-001', '5.1.9 遇有下列情况时，水平支承梁的设计应采取防倾倒措施，不得取消或改动销紧装置的作用，且应符合下列规定：1 水平支承如倾斜或由倾斜的托板支承以及偏心荷载情况存在时；2 梁由多杆件组成；', '["水平支承梁", "防倾倒措施", "销紧装置", "水平支承", "托板", "偏心荷载", "梁", "杆件"]', 0.95);
