INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1372, 12, 2090, '4.3.2', '<div style="text-align: center;">表 4.3.2 模板及其支架荷载效应组合的各项荷载标准值组合</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td rowspan="2" colspan="2">项 目</td><td colspan="2">参与组合的荷载类别</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>计算承载能力</td><td style=''text-align: center; word-wrap: break-word;''>验算挠度</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>1</td><td style=''text-align: center; word-wrap: break-word;''>平板和薄壳的模板及支架</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{1k} + G_{2k} + G_{3k} + Q_{1k} $</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{1k} + G_{2k} + G_{3k} $</td></tr></table>
<div style="text-align: center;">续表 4.3.2</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td rowspan="2" colspan="2">项目</td><td colspan="2">参与组合的荷载类别</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>计算承载能力</td><td style=''text-align: center; word-wrap: break-word;''>验算挠度</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>2</td><td style=''text-align: center; word-wrap: break-word;''>梁和拱模板的底板及支架</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{1k} + G_{2k} + G_{3k} + Q_{2k} $</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{1k} + G_{2k} + G_{3k} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>3</td><td style=''text-align: center; word-wrap: break-word;''>梁、拱、柱（边长不大于300mm）、墙（厚度不大于100mm）的侧面模板</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{4k} + Q_{2k} $</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{4k} $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>4</td><td style=''text-align: center; word-wrap: break-word;''>大体积结构、柱（边长大于300mm）、墙（厚度大于100mm）的侧面模板</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{4k} + Q_{3k} $</td><td style=''text-align: center; word-wrap: break-word;''>$ G_{4k} $</td></tr></table>
注：验算挠度应采用荷载标准值；计算承载能力应采用荷载设计值。', 'active', '2026-06-03 12:25:09.613036', '2026-06-03 12:25:09.612805', 'CP-4-3-2-001', '平板和薄壳的模板及支架：计算承载能力参与组合的荷载类别为$ G_{1k} + G_{2k} + G_{3k} + Q_{1k} $，验算挠度为$ G_{1k} + G_{2k} + G_{3k} $', '["平板和薄壳的模板及支架", "计算承载能力", "验算挠度"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1591, 12, 2153, '6.3.5', '1 当预组合模板采用桁架支模时，桁架与支点的连接应固定牢靠，桁架支承应采用平直通长的型钢或木方。
2 当预组合模板块较大时，应加钢楞后方可吊运。当组合模板为错缝拼配时，板下横楞应均匀布置，并应在模板端穿插销。
3 单块模就位安装，必须待支架搭设稳固、板下横楞与支架连接牢固后进行。
4 U形卡应按设计规定安装。', 'active', '2026-06-03 12:30:41.037475', '2026-06-03 12:30:41.033229', 'CP-6-3-5-004', '3 单块模就位安装，必须待支架搭设稳固、板下横楞与支架连接牢固后进行。', '["单块模", "支架", "板下横楞"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (160, 6, 1377, '5.1.8', '1 几种门架混合使用时，必须取支承力最小的门架作为设计依据；
2 荷载宜直接作用在门架两边立杆的轴线上，必要时可设横梁将荷载传于两立杆顶端，且应按单榀门架进行承力计算；
3 门架结构在相邻两榀之间应设工具式交叉支撑，使用的交叉支撑线刚度必须满足下式要求：
$$ \frac{I_{\mathrm{b}}}{L_{\mathrm{b}}}\geqslant0.03\frac{I}{h_{0}} $$
式中  $ I_{b} $ ——剪刀撑的截面惯性矩；
$ L_{b} $ ——剪刀撑的压曲长度；
I——门架的截面惯性矩；
$ h_{0} $ ——门架立杆高度。
4 当门架使用可调支座时，调节螺杆伸出长度不得大于  $ 150 \, mm $;
5 当露天门架支架立柱为群柱架时，高宽比不应大于 5；当高宽比大于 5 时，必须使用缆风绳，保证宽度方向的稳定。', 'active', '2026-06-02 06:32:14.53523', '2026-06-02 06:32:14.53499', 'CP-5-1-8-001', '5.1.8 用门式钢管脚手架作支架立柱时，应符合下列规定：1 几种门架混合使用时，必须取支承力最小的门架作为设计依据；', '["门式钢管脚手架", "支架立柱", "门架", "支承力"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (161, 6, 1377, '5.1.8', '1 几种门架混合使用时，必须取支承力最小的门架作为设计依据；
