INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (198, 6, 1409, '6.1.13', '6.1/14 吊运模板时，必须符合下列规定：
