INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (219, 6, 1426, '6.4.1', '', 'active', '2026-06-02 06:36:24.018331', '2026-06-02 06:36:24.018042', 'CP-6-4-1-001', '6.4.1 进入施工现场的爬升模板系统中的大模板、爬升支架、爬升设备、脚手架及附件等，应按施工组织设计及有关图纸验收，合格后方可使用。', '["爬升模板系统", "大模板", "爬升支架", "爬升设备", "脚手架", "附件"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1345, 12, 2087, '4.2.4', '', 'active', '2026-06-03 12:24:26.401252', '2026-06-03 12:24:26.400987', 'CP-4-2-4-001', '钢面板及支架作用荷载设计值可乘以系数 0.95 进行折减。', '["钢面板", "支架", "荷载设计值", "系数 0.95"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1346, 12, 2087, '4.2.4', '', 'active', '2026-06-03 12:24:26.402192', '2026-06-03 12:24:26.400987', 'CP-4-2-4-002', '当采用冷弯薄壁型钢时，其荷载设计值不应折减。', '["冷弯薄壁型钢", "荷载设计值"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1365, 12, 2091, '4.3.3', '## 1 模板结构设计荷载应包括：
侧向荷载：新浇混凝土侧向荷载和风荷载。当为工作状态时按6级风计算；非工作状态偶遇最大风力时，应采用临时固定措施；
竖向荷载：模板结构自重，机具、设备按实计算，施工人员按  $ 1.0 \, kN/m^{2} $ 采用；
混凝土对模板的上托力：当模板的倾角小于  $ 45^{\circ} $ 时，取  $ 3 \sim 5kN/m^{2} $；当模板的倾角大于或等于  $ 45^{\circ} $ 时，取  $ 5 \sim 12kN/m^{2} $；
新浇混凝土与模板的粘结力：按  $ 0.5 \, kN/m^{2} $ 采用，但确定混凝土与模板间摩擦力时，两者间的摩擦系数取  $ 0.4 \sim 0.5 $;
模板结构与滑轨的摩擦力：滚轮与轨道间的摩擦系数取0.05，滑块与轨道间的摩擦系数取0.15～0.50。
## 2 模板结构荷载组合应符合下列规定：
计算支承架的荷载组合：处于工作状态时，应为竖向荷载加迎墙面风荷载；处于非工作状态时，仅考虑风荷载；
计算附墙架的荷载组合：处于工作状态时，应为竖向荷载加背墙面风荷载；处于非工作状态时，仅考虑风荷载。', 'active', '2026-06-03 12:25:04.040728', '2026-06-03 12:25:04.040502', 'CP-4-3-3-001', '侧向荷载：新浇混凝土侧向荷载和风荷载。当为工作状态时按6级风计算；非工作状态偶遇最大风力时，应采用临时固定措施；', '["侧向荷载", "新浇混凝土", "风荷载", "工作状态", "临时固定措施"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1366, 12, 2091, '4.3.3', '## 1 模板结构设计荷载应包括：
