INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1620, 12, 2163, '6.4.8', '如需临时堆放少量材料或机具，必须及时取走，且不得超过设计荷载的规定。', 'active', '2026-06-03 12:31:17.491283', '2026-06-03 12:31:17.491038', 'CP-6-4-8-001', '脚手架上不应堆放材料，', '["脚手架", "材料"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (215, 6, 1422, '6.3.4', '1 安装独立梁模板时应设安全操作平台，并严禁操作人员站在独立梁底模或柱模支架上操作及上下通行。
2 底模与横楞应拉结好，横楞与支架、立柱应连接牢固。
3 安装梁侧模时，应边安装边与底模连接，当侧模高度多于 2 块时，应采取临时固定措施。
4 起拱应在侧模内外楞连固前进行。
5 单片预组合梁模，钢楞与板面的拉结应按设计规定制作，并应按设计吊点试吊无误后，方可正式吊运安装，侧模与支架支撑稳定后方准摘钩。', 'active', '2026-06-02 06:36:05.280155', '2026-06-02 06:36:05.27901', 'CP-6-3-4-002', '底模与横楞应拉结好，横楞与支架、立柱应连接牢固。', '["底模", "横楞", "支架", "立柱"]', 1.00);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (216, 6, 1422, '6.3.4', '1 安装独立梁模板时应设安全操作平台，并严禁操作人员站在独立梁底模或柱模支架上操作及上下通行。
