INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1583, 12, 2152, '6.3.4', '1 安装独立梁模板时应设安全操作平台，并严禁操作人员站在独立梁底模或柱模支架上操作及上下通行。
2 底模与横楞应拉结好，横楞与支架、立柱应连接牢固。
3 安装梁侧模时，应边安装边与底模连接，当侧模高度多于 2 块时，应采取临时固定措施。
4 起拱应在侧模内外楞连固前进行。
5 单片预组合梁模，钢楞与板面的拉结应按设计规定制作，并应按设计吊点试吊无误后，方可正式吊运安装，侧模与支架支撑稳定后方准摘钩。', 'active', '2026-06-03 12:30:36.488465', '2026-06-03 12:30:36.487396', 'CP-6-3-4-002', '2 底模与横楞应拉结好，横楞与支架、立柱应连接牢固。', '["底模", "横楞", "支架", "立柱"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1672, 12, 2188, '7.1.7', '', 'active', '2026-06-03 12:32:53.373438', '2026-06-03 12:32:53.37234', 'CP-7-1-7-002', '作业区应设围栏，其内不得有其他工种作业，并应设专人负责监护。', '["作业区", "围栏", "其他工种", "专人"]', 0.90);
