INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1399, 12, 2095, '4.4.2', '<div style="text-align: center;">表 4.4.2 组合钢模板及构配件的容许变形值(mm)</div>
