INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (343, 6, 1347, '3.5.7', '1 静曲强度：横向  $ 28.22 \sim 32.3 ~N / mm^{2} $ ；纵向  $ 52.62 \sim 67.21 ~N / mm^{2} $ ；
2 垂直表面抗拉强度：大于  $ 1.8N/mm^{2} $;
3 72h 吸水率：小于 5%;
4 72h 吸水膨胀率：小于 4%；
5 耐酸碱腐蚀性：在 1% 苛性钠中浸泡 24h，无软化及腐蚀现象；
6 耐水气性能：在水蒸气中喷蒸 24h 表面无软化及明显膨胀；
7 弹性模量：大于  $ 6.0 \times 10^{3} N/mm^{2} $', 'active', '2026-06-03 07:54:45.606235', '2026-06-03 07:54:45.603405', 'CP-3-5-7-003', '2 垂直表面抗拉强度：大于  $ 1.8N/mm^{2} $;', '["垂直表面抗拉强度"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1592, 12, 2153, '6.3.5', '1 当预组合模板采用桁架支模时，桁架与支点的连接应固定牢靠，桁架支承应采用平直通长的型钢或木方。
2 当预组合模板块较大时，应加钢楞后方可吊运。当组合模板为错缝拼配时，板下横楞应均匀布置，并应在模板端穿插销。
3 单块模就位安装，必须待支架搭设稳固、板下横楞与支架连接牢固后进行。
4 U形卡应按设计规定安装。', 'active', '2026-06-03 12:30:41.03826', '2026-06-03 12:30:41.033229', 'CP-6-3-5-005', '4 U形卡应按设计规定安装。', '["U形卡"]', 0.95);
