INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (505, 7, 1580, '6.0.1', '', 'active', '2026-06-03 11:34:25.331276', '2026-06-03 11:34:25.330945', 'CP-6-0-1-001', '检验批应由专业监理工程师组织施工单位项目专业质量检查员、专业工长等进行验收。', '["检验批", "专业监理工程师", "施工单位", "项目专业质量检查员", "专业工长"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (510, 7, 1583, '6.0.4', '', 'active', '2026-06-03 11:34:31.561614', '2026-06-03 11:34:31.561357', 'CP-6-0-4-001', '单位工程中的分包工程完工后，分包单位应对所承包的工程项目进行自检，并应按本标准规定的程序进行验收。', '["分包工程", "分包单位", "工程项目", "自检", "验收"]', 0.90);
