INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (344, 6, 1347, '3.5.7', '1 静曲强度：横向  $ 28.22 \sim 32.3 ~N / mm^{2} $ ；纵向  $ 52.62 \sim 67.21 ~N / mm^{2} $ ；
