INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (335, 6, 1346, '3.5.6', '1 不浸泡，不蒸煮：剪切强度  $ 1.4 \sim 1.8 N/mm^{2} $;
