INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1413, 12, 2103, '5.1.4', '升模板等的设计尚应符合现行国家标准《组合钢模板技术规范》GB 50214 和《滑动模板工程技术规范》GB 50113 的相应规定。', 'active', '2026-06-03 12:26:00.152316', '2026-06-03 12:26:00.152087', 'CP-5-1-4-001', '5.1.4 模板中的钢构件设计应符合现行国家标准《钢结构设计规范》GB 50017 和《冷弯薄壁型钢结构技术规范》GB 50018 的规定，其截面塑性发展系数应取 1.0。', '["模板", "钢构件", "钢结构设计规范", "GB 50017", "冷弯薄壁型钢结构技术规范", "GB 50018", "截面塑性发展系数"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1414, 12, 2103, '5.1.4', '升模板等的设计尚应符合现行国家标准《组合钢模板技术规范》GB 50214 和《滑动模板工程技术规范》GB 50113 的相应规定。', 'active', '2026-06-03 12:26:00.153105', '2026-06-03 12:26:00.152087', 'CP-5-1-4-002', '组合钢模板、大模板、滑升模板等的设计尚应符合现行国家标准《组合钢模板技术规范》GB 50214 和《滑动模板工程技术规范》GB 50113 的相应规定。', '["组合钢模板", "大模板", "滑升模板", "组合钢模板技术规范", "GB 50214", "滑动模板工程技术规范", "GB 50113"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1597, 12, 2157, '6.4.2', '做好原始记录。并应符合下列规定：
