INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (410, 6, 1384, '5.2.3', '对拉螺栓强度应按下列公式计算：
