INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (475, 7, 1566, '4.0.5', '', 'active', '2026-06-03 11:30:03.594504', '2026-06-03 11:30:03.594208', 'CP-4-0-5-001', '检验批可根据施工、质量控制和专业验收的需要，按工程量、楼层、施工段、变形缝进行划分。', '["检验批", "工程量", "楼层", "施工段", "变形缝"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (517, 7, 1584, '6.0.5', '', 'active', '2026-06-03 11:34:43.492406', '2026-06-03 11:34:43.49219', 'CP-6-0-5-001', '6.0.5 单位工程完工后，施工单位应组织有关人员进行自检。', '["单位工程", "施工单位", "自检"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (431, 6, 1398, '6.1.2', '1 模板安装应按设计与施工说明书顺序拼装。木杆、钢管、门架等支架立柱不得混用。
2 竖向模板和支架立柱支承部分安装在基土上时，应加设垫板，垫板应有足够强度和支承面积，且应中心承载。基土应坚实，并应有排水措施。对湿陷性黄土应有防水措施；对特别重要的结构工程可采用混凝土、打桩等措施防止支架柱下沉。对冻胀性土应有防冻融措施。
3 当满堂或共享空间模板支架立柱高度超过 8m 时，若地基土达不到承载要求，无法防止立柱下沉，则应先施工地面下的工程，再分层回填夯实基土，浇筑地面混凝土垫层，达到强度后方可支模。
4 模板及其支架在安装过程中，必须设置有效防倾覆的临时固定设施。
5 现浇钢筋混凝土梁、板，当跨度大于  $ 4 \, m $ 时，模板应起拱；当设计无具体要求时，起拱高度宜为全跨长度的  $ 1/1000 \sim 3/1000 $。
6 现浇多层或高层房屋和构筑物，安装上层模板及其支架应符合下列规定：
1）下层楼板应具有承受上层施工荷载的承载能力，否则应加设支撑支架；
2）上层支架立柱应对准下层支架立柱，并应在立柱底铺设垫板；
3）当采用悬臂吊模板、桁架支模方法时，其支撑结构的承载能力和刚度必须符合设计构造要求。
7 当层间高度大于 5m 时，应选用桁架支模或钢管立柱支模。当层间高度小于或等于 5m 时，可采用木立柱支模。', 'active', '2026-06-03 08:09:43.452136', '2026-06-03 08:09:43.447816', 'CP-6-1-2-006', '下层楼板应具有承受上层施工荷载的承载能力，否则应加设支撑支架；', '["下层楼板", "上层施工荷载", "支撑支架"]', 0.95);
