INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (436, 7, 1551, '3.0.1', '', 'active', '2026-06-03 11:28:00.617253', '2026-06-03 11:28:00.617009', 'CP-3-0-1-001', '施工现场应具有健全的质量管理体系、相应的施工技术标准、施工质量检验制度和综合施工质量水平评定考核制度。', '["施工现场", "质量管理体系", "施工技术标准", "施工质量检验制度", "综合施工质量水平评定考核制度"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (437, 7, 1551, '3.0.1', '', 'active', '2026-06-03 11:28:00.618385', '2026-06-03 11:28:00.617009', 'CP-3-0-1-002', '施工现场质量管理可按本标准附录 A 的要求进行检查记录。', '["施工现场质量管理", "本标准附录 A"]', 0.80);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (438, 7, 1553, '3.0.3', '1 建筑工程采用的主要材料、半成品、成品、建筑构配件、器具和设备应进行进场检验。凡涉及安全、节能、环境保护和主要使用功能的重要材料、产品，应按各专业工程施工规范、验收规范和设计文件等规定进行复验，并应经监理工程师检查认可；
2 各施工工序应按施工技术标准进行质量控制，每道施工工序完成后，经施工单位自检符合规定后，才能进行下道工序施工。各专业工种之间的相关工序应进行交接检验，并应记录；
3 对于监理单位提出检查要求的重要工序，应经监理工程师检查认可，才能进行下道工序施工。', 'active', '2026-06-03 11:28:04.615868', '2026-06-03 11:28:04.61563', 'CP-3-0-3-001', '1 建筑工程采用的主要材料、半成品、成品、建筑构配件、器具和设备应进行进场检验。凡涉及安全、节能、环境保护和主要使用功能的重要材料、产品，应按各专业工程施工规范、验收规范和设计文件等规定进行复验，并应经监理工程师检查认可；', '["主要材料", "半成品", "成品", "建筑构配件", "器具", "设备", "重要材料", "产品", "监理工程师"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (439, 7, 1553, '3.0.3', '1 建筑工程采用的主要材料、半成品、成品、建筑构配件、器具和设备应进行进场检验。凡涉及安全、节能、环境保护和主要使用功能的重要材料、产品，应按各专业工程施工规范、验收规范和设计文件等规定进行复验，并应经监理工程师检查认可；
