INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1629, 12, 2167, '6.5.2', '', 'active', '2026-06-03 12:31:32.186708', '2026-06-03 12:31:32.186417', 'CP-6-5-2-001', '飞模起吊时，应在吊离地面 0.5m 后停下，待飞模完全平衡后再起吊。', '["飞模"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1630, 12, 2167, '6.5.2', '', 'active', '2026-06-03 12:31:32.187527', '2026-06-03 12:31:32.186417', 'CP-6-5-2-002', '吊装应使用安全卡环，不得使用吊钩。', '["安全卡环", "吊钩"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (571, 8, 1629, '4.3.2', '1 应选取受力最大的杆件、构配件；
2 应选取跨距、间距变化和几何形状、承力特性改变部位的杆件、构配件；
3 应选取架体构造变化处或薄弱处的杆件、构配件；
4 当脚手架上有集中荷载作用时，尚应选取集中荷载作用范围内受力最大的杆件、构配件。', 'active', '2026-06-03 11:48:15.800401', '2026-06-03 11:48:15.797651', 'CP-4-3-2-004', '4 当脚手架上有集中荷载作用时，尚应选取集中荷载作用范围内受力最大的杆件、构配件。', '["集中荷载", "杆件", "构配件"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (574, 8, 1635, '4.4.1', '', 'active', '2026-06-03 11:48:31.07861', '2026-06-03 11:48:31.078336', 'CP-4-4-1-001', '4.4.1 脚手架构造措施应合理、齐全、完整，并应保证架体传力清晰、受力均匀。', '["脚手架", "构造措施", "架体"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (585, 8, 1638, '4.4.4', '1 作业脚手架、满堂支撑脚手架、附着式升降脚手架作业层应满铺脚手板，并应满足稳固可靠的要求。当作业层边缘与结构外表面的距离大于150mm时，应采取防护措施。
2 采用挂钩连接的钢脚手板，应带有自锁装置且与作业层水平杆锁紧。
3 木脚手板、竹串片脚手板、竹芭脚手板应有可靠的水平杆支承，并应绑扎稳固。
4 脚手架作业层外边缘应设置防护栏杆和挡脚板。
5 作业脚手架底层脚手板应采取封闭措施。
6 沿所施工建筑物每 3 层或高度不大于 10m 处应设置一层水平防护。
7 作业层外侧应采用安全网封闭。当采用密目安全网封闭时，密目安全网应满足阻燃要求。
8 脚手板伸出横向水平杆以外的部分不应大于  $ 200 \, mm $。', 'active', '2026-06-03 11:48:56.622386', '2026-06-03 11:48:56.622143', 'CP-4-4-4-001', '4.4.4 脚手架作业层应采取安全防护措施，并应符合下列规定：1 作业脚手架、满堂支撑脚手架、附着式升降脚手架作业层应满铺脚手板，并应满足稳固可靠的要求。当作业层边缘与结构外表面的距离大于150mm时，应采取防护措施。', '["脚手架作业层", "作业脚手架", "满堂支撑脚手架", "附着式升降脚手架", "脚手板", "作业层边缘", "结构外表面"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (586, 8, 1638, '4.4.4', '1 作业脚手架、满堂支撑脚手架、附着式升降脚手架作业层应满铺脚手板，并应满足稳固可靠的要求。当作业层边缘与结构外表面的距离大于150mm时，应采取防护措施。
2 采用挂钩连接的钢脚手板，应带有自锁装置且与作业层水平杆锁紧。
3 木脚手板、竹串片脚手板、竹芭脚手板应有可靠的水平杆支承，并应绑扎稳固。
4 脚手架作业层外边缘应设置防护栏杆和挡脚板。
5 作业脚手架底层脚手板应采取封闭措施。
6 沿所施工建筑物每 3 层或高度不大于 10m 处应设置一层水平防护。
7 作业层外侧应采用安全网封闭。当采用密目安全网封闭时，密目安全网应满足阻燃要求。
8 脚手板伸出横向水平杆以外的部分不应大于  $ 200 \, mm $。', 'active', '2026-06-03 11:48:56.623165', '2026-06-03 11:48:56.622143', 'CP-4-4-4-002', '2 采用挂钩连接的钢脚手板，应带有自锁装置且与作业层水平杆锁紧。', '["挂钩连接的钢脚手板", "自锁装置", "作业层水平杆"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (587, 8, 1638, '4.4.4', '1 作业脚手架、满堂支撑脚手架、附着式升降脚手架作业层应满铺脚手板，并应满足稳固可靠的要求。当作业层边缘与结构外表面的距离大于150mm时，应采取防护措施。
2 采用挂钩连接的钢脚手板，应带有自锁装置且与作业层水平杆锁紧。
3 木脚手板、竹串片脚手板、竹芭脚手板应有可靠的水平杆支承，并应绑扎稳固。
4 脚手架作业层外边缘应设置防护栏杆和挡脚板。
