INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1402, 12, 2095, '4.4.2', '<div style="text-align: center;">表 4.4.2 组合钢模板及构配件的容许变形值(mm)</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>部件名称</td><td style=''text-align: center; word-wrap: break-word;''>容许变形值</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>钢模板的面板</td><td style=''text-align: center; word-wrap: break-word;''>$ \leqslant1.5 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>单块钢模板</td><td style=''text-align: center; word-wrap: break-word;''>$ \leqslant1.5 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>钢楞</td><td style=''text-align: center; word-wrap: break-word;''>L/500 或  $ \leqslant3.0 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>柱箍</td><td style=''text-align: center; word-wrap: break-word;''>B/500 或  $ \leqslant3.0 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>桁架、钢模板结构体系</td><td style=''text-align: center; word-wrap: break-word;''>L/1000</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>支撑系统累计</td><td style=''text-align: center; word-wrap: break-word;''>$ \leqslant4.0 $</td></tr></table>
注：L 为计算跨度，B 为柱宽。', 'active', '2026-06-03 12:25:36.389906', '2026-06-03 12:25:36.386858', 'CP-4-4-2-005', '桁架、钢模板结构体系容许变形值L/1000', '["桁架", "钢模板结构体系"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1542, 12, 2144, '6.2.3', '1 木立柱宜选用整料，当不能满足要求时，立柱的接头不宜超过 1 个，并应采用对接夹板接头方式。立柱底部可采用垫块垫高，但不得采用单码砖垫高，垫高高度不得超过 300mm。
2 木立柱底部与垫木之间应设置硬木对角楔调整标高，并应用铁钉将其固定在垫木上。
3 木立柱间距、扫地杆、水平拉杆、剪刀撑的设置应符合本规范 6.1.9 条的规定，严禁使用板皮替代规定的拉杆。
4 所有单立柱支撑应在底垫木和梁底模板的中心，并应与底部垫木和顶部梁底模板紧密接触，且不得承受偏心荷载。
5 当仅为单排立柱时，应在单排立柱的两边每隔 3m 加设斜支撑，且每边不得少于 2 根，斜支撑与地面的夹角应为  $ 60^{\circ} $。', 'active', '2026-06-03 12:29:47.31458', '2026-06-03 12:29:47.313519', 'CP-6-2-3-002', '2 木立柱底部与垫木之间应设置硬木对角楔调整标高，并应用铁钉将其固定在垫木上。', '["木立柱", "垫木", "硬木对角楔", "铁钉"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1632, 12, 2168, '6.5.3', '', 'active', '2026-06-03 12:31:36.112379', '2026-06-03 12:31:36.111352', 'CP-6-5-3-002', '外侧应另加设安全网，同时应设置楼层护栏。', '["安全网", "楼层护栏"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (598, 8, 1641, '4.4.7', '1 每道剪刀撑的宽度应为 4 跨～6 跨，且不应小于 6m，也不应大于 9m；剪刀撑斜杆与水平面的倾角应在  $ 45^{\circ} \sim 60^{\circ} $ 之间；
2 当搭设高度在 24m 以下时，应在架体两端、转角及中间每隔不超过 15m 各设置一道剪刀撑，并应由底至顶连续设置；当搭设高度在 24m 及以上时，应在全外侧立面上由底至顶连续设置；
3 悬挑脚手架、附着式升降脚手架应在全外侧立面上由底至顶连续设置。', 'active', '2026-06-03 11:49:06.176514', '2026-06-03 11:49:06.174744', 'CP-4-4-7-003', '3 悬挑脚手架、附着式升降脚手架应在全外侧立面上由底至顶连续设置。', '["悬挑脚手架", "附着式升降脚手架", "全外侧立面"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (602, 8, 1645, '4.4.11', '', 'active', '2026-06-03 11:49:15.721732', '2026-06-03 11:49:15.721461', 'CP-4-4-11-001', '4.4.11 临街作业脚手架的外侧立面、转角处应采取有效硬防护措施。', '["临街作业脚手架", "外侧立面", "转角处", "硬防护措施"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (603, 8, 1643, '4.4.9', '1 竖向主框架、水平支承桁架应采用桁架或刚架结构，杆件应采用焊接或螺栓连接；
2 应设有防倾、防坠、停层、荷载、同步升降控制装置，各类装置应灵敏可靠；
