INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1427, 12, 2106, '5.1.7', '1 连接扣件和钢管立杆底座应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定；
2 承重的支架柱，其荷载应直接作用于立杆的轴线上，严禁承受偏心荷载，并应按单立杆轴心受压计算；钢管的初始弯曲率不得大于1/1000，其壁厚应按实际检查结果计算；
3 当露天支架立柱为群柱架时，高宽比不应大于 5；当高宽比大于 5 时，必须加设抛撑或缆风绳，保证宽度方向的稳定。', 'active', '2026-06-03 12:26:17.537796', '2026-06-03 12:26:17.537553', 'CP-5-1-7-001', '5.1.7 用扣件式钢管脚手架作支架立柱时，应符合下列规定：1 连接扣件和钢管立杆底座应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定；', '["扣件式钢管脚手架", "支架立柱", "连接扣件", "钢管立杆底座"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1428, 12, 2106, '5.1.7', '1 连接扣件和钢管立杆底座应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定；
2 承重的支架柱，其荷载应直接作用于立杆的轴线上，严禁承受偏心荷载，并应按单立杆轴心受压计算；钢管的初始弯曲率不得大于1/1000，其壁厚应按实际检查结果计算；
