INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (762, 11, 1807, '4.2.4', '1 永久荷载与可变荷载（不含风荷载）标准值总和不大于  $ 4.2 \, kN/m^{2} $ 时，施工均布荷载标准值应按本规范表 4.2.2 采用；
