INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (863, 11, 1847, '5.3.6', '', 'active', '2026-06-03 12:07:36.926226', '2026-06-03 12:07:36.925954', 'CP-5-3-6-001', '5.3.6 当满堂脚手架立杆间距不大于  $ 1.5m 	imes 1.5m $，架体四周及中间与建筑物结构进行刚性连接，并且刚性连接点的水平间距不大于  $ 4.5m $，竖向间距不大于  $ 3.6m $ 时，可按本规范第 5.2.6 条～第 5.2.10 条双排脚手架的规定进行计算。', '["满堂脚手架", "立杆间距", "架体", "建筑物结构", "刚性连接", "刚性连接点", "水平间距", "竖向间距", "双排脚手架"]', 0.95);
