INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (844, 11, 1831, '5.2.6', '不组合风荷载时： $ \frac{N}{\varphi A} \leqslant f $
