INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (980, 11, 1911, '6.7.2', '1 斜道应附着外脚手架或建筑物设置；
