INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (924, 11, 1879, '6.2.4', '1 作业层脚手板应铺满、铺稳、铺实。
