INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (991, 11, 1917, '6.8.4', '8m 由底至顶设置连续竖向剪刀撑。当架体搭设高度在 8m 以下时，应在架顶部设置连续水平剪刀撑；当架体搭设高度在 8m 及以上时，应在架体底部、顶部及竖向间隔不超过 8m 分别设置连续水平剪刀撑。水平剪刀撑宜在竖向剪刀撑斜杆相交平面设置。剪刀撑宽度应为 6m～8m。', 'active', '2026-06-03 12:12:44.458835', '2026-06-03 12:12:44.458607', 'CP-6-8-4-001', '6.8.4 满堂脚手架应在架体外侧四周及内部纵、横向每 6m 至8m 由底至顶设置连续竖向剪刀撑。', '["满堂脚手架", "架体", "外侧四周", "内部", "纵、横向", "竖向剪刀撑"]', 0.95);
