INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1037, 11, 1931, '6.9.7', '和中部与结构柱进行刚性连接，连墙件水平间距应为6m～9m，竖向间距应为2m～3m。在无结构柱部位应采取预埋钢管等措施与建筑结构进行刚性连接，在有空间部位，满堂支撑架宜超出顶部加载区投影范围向外延伸布置（2～3）跨。支撑架高宽比不应大于3。', 'active', '2026-06-03 12:13:52.02042', '2026-06-03 12:13:52.020144', 'CP-6-9-7-001', '6.9.7 当满堂支撑架高宽比不满足本规范附录 C 表 C-2～表 C-5 的规定（高宽比大于 2 或 2.5）时，满堂支撑架应在支架的四周和中部与结构柱进行刚性连接，连墙件水平间距应为6m～9m，竖向间距应为2m～3m。', '["满堂支撑架", "高宽比", "结构柱", "连墙件", "水平间距", "竖向间距"]', 0.95);
