INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1121, 11, 1973, '7.4.3', '', 'active', '2026-06-03 12:16:28.691655', '2026-06-03 12:16:28.690627', 'CP-7-4-3-002', '当单、双排脚手架采取分段、分立面拆除时，对不拆除的脚手架两端，应先按本规范第 6.4.4 条、第 6.6.4 条、第 6.6.5 条的有关规定设置连墙件和横向斜撑加固。', '["单、双排脚手架", "连墙件", "横向斜撑"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1136, 11, 1980, '8.1.2', '1 表面锈蚀深度应符合本规范表 8.1.8 序号 3 的规定。锈蚀检查应每年一次。检查时，应在锈蚀严重的钢管中抽取三根，在每根锈蚀严重的部位横向截断取样检查，当锈蚀深度超过规定值时不得使用。
2 钢管弯曲变形应符合本规范表 8.1.8 序号 4 的规定。', 'active', '2026-06-03 12:16:55.011457', '2026-06-03 12:16:55.011184', 'CP-8-1-2-001', '8.1.2 旧钢管的检查应符合下列规定：1 表面锈蚀深度应符合本规范表 8.1.8 序号 3 的规定。', '["旧钢管", "表面锈蚀深度", "本规范表 8.1.8 序号 3"]', 0.95);
