INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1150, 11, 1988, '8.2.1', '1 基础完工后及脚手架搭设前；
