INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1222, 11, 1999, '9.0.6', '', 'active', '2026-06-03 12:18:18.710081', '2026-06-03 12:18:18.70883', 'CP-9-0-6-002', '当出现异常情况时，应立即停止施工，并应迅速撤离作业面上人员。', '["异常情况", "施工", "作业面", "人员"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1092, 11, 1962, '7.3.6', '1 搭设横向水平杆应符合本规范第 6.2.2 条的规定；
2 双排脚手架横向水平杆的靠墙一端至墙装饰面的距离不应大于 100mm；
3 单排脚手架的横向水平杆不应设置在下列部位：
1）设计上不允许留脚手眼的部位；
2）过梁上与过梁两端成  $ 60^{\circ} $ 角的三角形范围内及过梁净跨度 1/2 的高度范围内；
3）宽度小于1m的窗间墙；
4）梁或梁垫下及其两侧各 500mm 的范围内；
5）砖砌体的门窗洞口两侧 200mm 和转角处 450mm 的范围内，其他砌体的门窗洞口两侧 300mm 和转角处 600mm 的范围内；
6）墙体厚度小于或等于180mm；
7）独立或附墙砖柱，空斗砖墙、加气块墙等轻质墙体；
8）砌筑砂浆强度等级小于或等于 M2.5 的砖墙。', 'active', '2026-06-03 12:15:50.612351', '2026-06-03 12:15:50.60997', 'CP-7-3-6-004', '2）过梁上与过梁两端成  $ 60^{\circ} $ 角的三角形范围内及过梁净跨度 1/2 的高度范围内；', '["过梁", "三角形范围", "净跨度"]', 0.90);
