INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1149, 11, 1985, '8.1.7', '1 应有产品质量合格证，其质量应符合本规范第 3.4 节的规定；
2 应有质量检验报告，可调托撑抗压承载力应符合本规范第 5.1.7 条的规定；
3 可调托撑支托板厚不应小于 5mm，变形不应大于 1mm；
4 严禁使用有裂缝的支托板、螺母。', 'active', '2026-06-03 12:17:21.072341', '2026-06-03 12:17:21.070037', 'CP-8-1-7-004', '4 严禁使用有裂缝的支托板、螺母。', '["支托板", "螺母"]', 0.95);
