INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1265, 12, 2060, '3.3.3', '', 'active', '2026-06-03 12:22:12.456551', '2026-06-03 12:22:12.456323', 'CP-3-3-3-001', '3.3.3 用于模板体系的原木、方木和板材可采用目测法分级。', '["模板体系", "原木", "方木", "板材", "目测法"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1266, 12, 2060, '3.3.3', '', 'active', '2026-06-03 12:22:12.457339', '2026-06-03 12:22:12.456323', 'CP-3-3-3-002', '选材应符合现行国家标准《木结构设计规范》GB 50005 的规定，不得利用商品材的等级标准替代。', '["选材", "现行国家标准", "《木结构设计规范》GB 50005", "商品材的等级标准"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1267, 12, 2064, '3.3.7', '', 'active', '2026-06-03 12:22:26.207031', '2026-06-03 12:22:26.206805', 'CP-3-3-7-001', '3.3.7 当需要对模板结构或构件木材的强度进行测试验证时，应按现行国家标准《木结构设计规范》GB 50005 的检验标准进行。', '["模板结构", "构件木材", "《木结构设计规范》GB 50005"]', 0.90);
