INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1232, 11, 2005, '9.0.12', '', 'active', '2026-06-03 12:18:43.868175', '2026-06-03 12:18:43.86793', 'CP-9-0-12-001', '9.0.12 单、双排脚手架、悬挑式脚手架沿架体外围应用密目式安全网全封闭', '["单排脚手架", "双排脚手架", "悬挑式脚手架", "架体", "密目式安全网"]', 0.90);
