INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1247, 12, 2047, '3.1.2', '1 钢材应符合现行国家标准《碳素结构钢》GB/T 700、《低合金高强度结构钢》GB/T 1591 的规定。
