INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1237, 11, 2011, '9.0.18', '', 'active', '2026-06-03 12:19:01.841872', '2026-06-03 12:19:01.841624', 'CP-9-0-18-001', '9.0.18 工地临时用电线路的架设及脚手架接地、避雷措施等，应按现行行业标准《施工现场临时用电安全技术规范》JGJ 46的有关规定执行。', '["工地临时用电线路", "脚手架接地", "避雷措施"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1241, 12, 2048, '3.1.3', '腾钢：
