INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1251, 12, 2047, '3.1.2', '1 钢材应符合现行国家标准《碳素结构钢》GB/T 700、《低合金高强度结构钢》GB/T 1591 的规定。
2 钢管应符合现行国家标准《直缝电焊钢管》GB/T 13793或《低压流体输送用焊接钢管》GB/T 3092中规定的Q235普通钢管的要求，并应符合现行国家标准《碳素结构钢》GB/T 700中Q235A级钢的规定。不得使用有严重锈蚀、弯曲、压扁及裂纹的钢管。
3 钢铸件应符合现行国家标准《一般工程用铸造碳钢件》GB/T 11352 中规定的 ZG 200-420、ZG 230-450、ZG 270-500 和 ZG 310-570 号钢的要求。
4 钢管扣件应符合现行国家标准《钢管脚手架扣件》GB 15831 的规定。
5 连接用的焊条应符合现行国家标准《碳钢焊条》GB/T 5117 或《低合金钢焊条》GB/T 5118 中的规定。
6 连接用的普通螺栓应符合现行国家标准《六角头螺栓 C 级》GB/T 5780 和《六角头螺栓》GB/T 5782 的规定。
7 组合钢模板及配件制作质量应符合现行国家标准《组合钢模板技术规范》GB 50214 的规定。', 'active', '2026-06-03 12:21:46.956913', '2026-06-03 12:21:46.953941', 'CP-3-1-2-005', '5 连接用的焊条应符合现行国家标准《碳钢焊条》GB/T 5117 或《低合金钢焊条》GB/T 5118 中的规定。', '["焊条", "《碳钢焊条》GB/T 5117", "《低合金钢焊条》GB/T 5118"]', 0.95);
