INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1280, 12, 2063, '3.3.6', '1 应选择天然缺陷和干燥缺陷少、耐腐朽性较好的树种木材；
