INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1454, 12, 2114, '5.2.3', '对拉螺栓强度应按下列公式计算：
$$ N=a b F_{s}\quad 軒 \quad. $$
<div style="text-align: center;"><img src="imgs/img_in_image_box_250_123_628_347.jpg" alt="Image" width="40%" /></div>
<div style="text-align: center;">图 5.2.2-4 桁架节点集中荷载布置图（全跨等分）</div>
<div style="text-align: center;"><img src="imgs/img_in_image_box_282_425_662_691.jpg" alt="Image" width="40%" /></div>
<div style="text-align: center;">图 5.2.2-5 桁架节点集中荷载布置图（中间等分）</div>
$$ N_{\mathrm{t}}^{\mathrm{b}}=A_{\mathrm{n}}f_{\mathrm{t}}^{\mathrm{b}} $$
$$ N_{\mathrm{t}}^{\mathrm{b}}>N $$
式中 N —— 对拉螺栓最大轴力设计值；
$ N_{t}^{b} $ ——对拉螺栓轴向拉力设计值，按本规范表 5.2.3 采用；
a——对拉螺栓横向间距；
b——对拉螺栓竖向间距；
$ F_{s} $ ——新浇混凝土作用于模板上的侧压力、振捣混凝土对垂直模板产生的水平荷载或倾倒混凝土时作用于模板上的侧压力设计值：
$$ F_{\mathrm{s}}=0.95(r_{\mathrm{G}}F+r_{\mathrm{Q}}Q_{3\mathrm{k}}) 或 F_{\mathrm{s}}=0.95(r_{\mathrm{G}}G_{4\mathrm{k}}+r_{\mathrm{Q}}Q_{3\mathrm{k}}); $$
其中 0.95 为荷载值折减系数；
$ A_{n} $ ——对拉螺栓净截面面积，按本规范表 5.2.3 采用；
$ f_{t}^{b} $ ——螺栓的抗拉强度设计值，按本规范附录 A 表 A.1.1-4 采用。
<div style="text-align: center;">表 5.2.3 对拉螺栓轴向拉力设计值 ( $ N_{t}^{b} $)</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>螺栓直径 (mm)</td><td style=''text-align: center; word-wrap: break-word;''>螺栓内径 (mm)</td><td style=''text-align: center; word-wrap: break-word;''>净截面面积 (mm²)</td><td style=''text-align: center; word-wrap: break-word;''>重量 (N/m)</td><td style=''text-align: center; word-wrap: break-word;''>轴向拉力设计值 N‖ (kN)</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>M12</td><td style=''text-align: center; word-wrap: break-word;''>9.85</td><td style=''text-align: center; word-wrap: break-word;''>76</td><td style=''text-align: center; word-wrap: break-word;''>8.9</td><td style=''text-align: center; word-wrap: break-word;''>12.9</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>M14</td><td style=''text-align: center; word-wrap: break-word;''>11.55</td><td style=''text-align: center; word-wrap: break-word;''>105</td><td style=''text-align: center; word-wrap: break-word;''>12.1</td><td style=''text-align: center; word-wrap: break-word;''>17.8</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>M16</td><td style=''text-align: center; word-wrap: break-word;''>13.55</td><td style=''text-align: center; word-wrap: break-word;''>144</td><td style=''text-align: center; word-wrap: break-word;''>15.8</td><td style=''text-align: center; word-wrap: break-word;''>24.5</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>M18</td><td style=''text-align: center; word-wrap: break-word;''>14.93</td><td style=''text-align: center; word-wrap: break-word;''>174</td><td style=''text-align: center; word-wrap: break-word;''>20.0</td><td style=''text-align: center; word-wrap: break-word;''>29.6</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>M20</td><td style=''text-align: center; word-wrap: break-word;''>16.93</td><td style=''text-align: center; word-wrap: break-word;''>225</td><td style=''text-align: center; word-wrap: break-word;''>24.6</td><td style=''text-align: center; word-wrap: break-word;''>38.2</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>M22</td><td style=''text-align: center; word-wrap: break-word;''>18.93</td><td style=''text-align: center; word-wrap: break-word;''>282</td><td style=''text-align: center; word-wrap: break-word;''>29.6</td><td style=''text-align: center; word-wrap: break-word;''>47.9</td></tr></table>', 'active', '2026-06-03 12:27:18.153428', '2026-06-03 12:27:18.149177', 'CP-5-2-3-006', '<tr><td style=''text-align: center; word-wrap: break-word;''>M14</td><td style=''text-align: center; word-wrap: break-word;''>11.55</td><td style=''text-align: center; word-wrap: break-word;''>105</td><td style=''text-align: center; word-wrap: break-word;''>12.1</td><td style=''text-align: center; word-wrap: break-word;''>17.8</td></tr>', '["M14", "螺栓内径", "净截面面积", "重量", "轴向拉力设计值"]', 0.95);
