INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1465, 12, 2118, '5.2.7', '', 'active', '2026-06-03 12:27:37.492563', '2026-06-03 12:27:37.492194', 'CP-5-2-7-001', '5.2.7 框架和剪力墙的模板、钢筋全部安装完毕后，应验算在本地区规定的风压作用下，整个模板系统的稳定性。', '["框架", "剪力墙", "模板", "钢筋", "风压", "模板系统"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1466, 12, 2118, '5.2.7', '', 'active', '2026-06-03 12:27:37.493391', '2026-06-03 12:27:37.492194', 'CP-5-2-7-002', '其验算方法应将要求的风力与模板系统、钢筋的自重乘以相应荷载分项系数后，求其合力作用线不得超过背风面的柱脚或墙底脚的外边。', '["风力", "模板系统", "钢筋", "荷载分项系数", "合力作用线", "柱脚", "墙底脚"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1469, 12, 2117, '5.2.6', '$$ p=\frac{N}{A}\leqslant m_{\mathrm{f}}f_{\mathrm{ak}} $$
式中 p —— 立柱底垫木的底面平均压力；
N——上部立柱传至垫木顶面的轴向力设计值；
A——垫木底面面积；
$ f_{ak} $ ——地基土承载力设计值，应按现行国家标准《建筑地基基础设计规范》GB 50007 的规定或工程地质报告提供的数据采用；
$ m_{f} $ ——立柱垫木地基土承载力折减系数，应按表 5.2.6 采用。
<div style="text-align: center;">表 5.2.6 地基土承载力折减系数 $  (m_{f})  $</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td rowspan="2">地基土类别</td><td colspan="2">折减系数</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>支承在原土上时</td><td style=''text-align: center; word-wrap: break-word;''>支承在回填土上时</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>碎石土、砂土、多年填积土</td><td style=''text-align: center; word-wrap: break-word;''>0.8</td><td style=''text-align: center; word-wrap: break-word;''>0.4</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>粉土、黏土</td><td style=''text-align: center; word-wrap: break-word;''>0.9</td><td style=''text-align: center; word-wrap: break-word;''>0.5</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>岩石、混凝土</td><td style=''text-align: center; word-wrap: break-word;''>1.0</td><td style=''text-align: center; word-wrap: break-word;''>—</td></tr></table>
注：1 立柱基础应有良好的排水措施，支安垫木前应适当洒水将原土表面夯实夯平；
2 回填土应分层夯实，其各类回填土的十重度应达到所要求的密实度。', 'active', '2026-06-03 12:27:51.171352', '2026-06-03 12:27:51.17112', 'CP-5-2-6-001', '5.2.6 立柱底地基承载力应按下列公式计算：$$ p=\frac{N}{A}\leqslant m_{\mathrm{f}}f_{\mathrm{ak}} $$', '["立柱底地基", "公式"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1476, 12, 2120, '5.3.1', '<div style="text-align: center;"><img src="imgs/img_in_image_box_336_572_606_1132.jpg" alt="Image" width="28%" /></div>
