INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1518, 12, 2137, '6.1.11', '', 'active', '2026-06-03 12:29:13.694675', '2026-06-03 12:29:13.694445', 'CP-6-1-11-001', '6.1.11 组合钢模板、滑升模板等的构造与安装，尚应符合现行国家标准《组合钢模板技术规范》GB 50214 和《滑动模板工程技术规范》GB 50113 的相应规定。', '["组合钢模板", "滑升模板", "构造", "安装", "《组合钢模板技术规范》GB 50214", "《滑动模板工程技术规范》GB 50113"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1537, 12, 2142, '6.2.1', '1 采用伸缩式桁架时，其搭接长度不得小于 500mm，上下弦连接销钉规格、数量应按设计规定，并应采用不少于 2 个 U 形卡或钢销钉销紧，2 个 U 形卡距或销距不得小于 400mm。
