INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1693, 12, 2200, '7.2.3', '', 'active', '2026-06-03 12:33:41.686203', '2026-06-03 12:33:41.685981', 'CP-7-2-3-001', '7.2.3 当拆除 4~8m 跨度的梁下立柱时，应先从跨中开始，对称地分别向两端拆除。', '["梁下立柱", "跨中", "两端"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1548, 12, 2146, '6.2.5', '1 门架的跨距和间距应按设计规定布置，间距宜小于1.2m；支撑架底部垫木上应设固定底座或可调底座。门架、调节架及可调底座，其高度应按其支撑的高度确定。
2 门架支撑可沿梁轴线垂直和平行布置。当垂直布置时，
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td style=''text-align: center; word-wrap: break-word;''>Q</td><td style=''text-align: center; word-wrap: break-word;''>O</td><td style=''text-align: center; word-wrap: break-word;''>O</td></tr></table>
<div style="text-align: center;">图 6.2.4-3 剪刀撑布置图（三）</div>
在两门架间的两侧应设置交叉支撑；当平行布置时，在两门架间的两侧亦应设置交叉支撑，交叉支撑应与立杆上的锁销锁牢，上下门架的组装连接必须设置连接棒及锁臂。
3 当门架支撑宽度为 4 跨及以上或 5 个间距及以上时，应在周边底层、顶层、中间每 5 列、5 排在每门架立杆跟部设  $ \phi48mm\times3.5mm $ 通长水平加固杆，并应采用扣件与门架立杆扣牢。
4 当门架支撑高度超过  $ 8 \, m $ 时，应按本规范第 6.2.4 条的规定执行，剪刀撑不应大于 4 个间距，并应采用扣件与门架立杆
扣牢。
5 顶部操作层应采用挂扣式脚手板满铺。', 'active', '2026-06-03 12:30:08.041879', '2026-06-03 12:30:08.041648', 'CP-6-2-5-001', '1 门架的跨距和间距应按设计规定布置，间距宜小于1.2m；支撑架底部垫木上应设固定底座或可调底座。门架、调节架及可调底座，其高度应按其支撑的高度确定。', '["门架", "跨距", "间距", "支撑架底部垫木", "固定底座", "可调底座", "调节架"]', 0.95);
