INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1593, 12, 2154, '6.3.6', '1 安装圈梁、阳台、雨篷及挑檐等模板时，其支撑应独立设置，不得支搭在施工脚手架上。
