INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1702, 12, 2206, '7.3.2', '1 柱模拆除应分别采用分散拆和分片拆 2 种方法。分散拆除的顺序应为：
拆除拉杆或斜撑、自上而下拆除柱箍或横楞、拆除竖楞，自上而下拆除配件及模板、运走分类堆放、清理、拔钉、钢模维修、刷防锈油或脱模剂、入库备用。
分片拆除的顺序应为：
拆除全部支撑系统、自上而下拆除柱箍及横楞、拆掉柱角 U 形卡、分 2 片或 4 片拆除模板、原地清理、刷防锈油或脱模剂、分片运至新支模地点备用。
2 柱子拆下的模板及配件不得向地面抛掷。', 'active', '2026-06-03 12:34:08.566369', '2026-06-03 12:34:08.566123', 'CP-7-3-2-001', '7.3.2 拆除柱模应符合下列规定：1 柱模拆除应分别采用分散拆和分片拆 2 种方法。', '["柱模", "分散拆", "分片拆"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1756, 12, 2235, '8.0.5', '1 立柱底部基土应回填夯实。
