INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1763, 12, 2240, '8.0.10', '', 'active', '2026-06-03 12:36:02.130525', '2026-06-03 12:36:02.130248', 'CP-8-0-10-001', '8.0.10 施工用的临时照明和行灯的电压不得超过  $ 36 \, V $；当为满堂模板、钢支架及特别潮湿的环境时，不得超过  $ 12 \, V $。', '["临时照明", "行灯", "电压", "满堂模板", "钢支架", "环境"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1764, 12, 2240, '8.0.10', '', 'active', '2026-06-03 12:36:02.131333', '2026-06-03 12:36:02.130248', 'CP-8-0-10-002', '照明行灯及机电设备的移动线路应采用绝缘橡胶套电缆线。', '["照明行灯", "机电设备", "移动线路", "绝缘橡胶套电缆线"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1777, 12, 2246, '8.0.16', '', 'active', '2026-06-03 12:36:19.244891', '2026-06-03 12:36:19.244659', 'CP-8-0-16-001', '8.0.16 模板施工中应设专人负责安全检查，发现问题应报告有关人员处理。', '["模板施工", "专人", "安全检查", "有关人员"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1778, 12, 2246, '8.0.16', '', 'active', '2026-06-03 12:36:19.245635', '2026-06-03 12:36:19.244659', 'CP-8-0-16-002', '当遇险情时，应立即停工和采取应急措施；待修复或排除险情后，方可继续施工。', '["险情", "应急措施", "施工"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1783, 12, 2251, '8.0.21', '', 'active', '2026-06-03 12:36:39.692957', '2026-06-03 12:36:39.692732', 'CP-8-0-21-001', '使用后的木模板应拔除铁钉，分类进库，堆放整齐。', '["木模板", "铁钉"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1784, 12, 2251, '8.0.21', '', 'active', '2026-06-03 12:36:39.693742', '2026-06-03 12:36:39.692732', 'CP-8-0-21-002', '若为露天堆放，顶面应遮防雨篷布。', '["露天堆放", "防雨篷布"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1708, 12, 2207, '7.3.3', '1 墙模分散拆除顺序应为：
拆除斜撑或斜拉杆、自上而下拆除外楞及对拉螺栓、分层自上而下拆除木楞或钢楞及零配件和模板、运走分类堆放、拔钉清理或清理检修后刷防锈油或脱模剂、入库备用。
## 2 预组拼大块墙模拆除顺序应为：
拆除全部支撑系统、拆卸大块墙模接缝处的连接型钢及零配件、拧去固定埋设件的螺栓及大部分对拉螺栓、挂上吊装绳扣并略拉紧吊绳后，拧下剩余对拉螺栓，用方木均匀敲击大块墙模立楞及钢模板，使其脱离墙体，用撬棍轻轻外撬大块墙模板使全部脱离，指挥起吊、运走、清理、刷防锈油或脱模剂备用。
3 拆除每一大块墙模的最后 2 个对拉螺栓后，作业人员应撤离大模板下侧，以后的操作均应在上部进行。个别大块模板拆除后产生局部变形者应及时整修好。
4 大块模板起吊时，速度要慢，应保持垂直，严禁模板碰撞墙体。', 'active', '2026-06-03 12:34:11.989677', '2026-06-03 12:34:11.987753', 'CP-7-3-3-003', '3 拆除每一大块墙模的最后 2 个对拉螺栓后，作业人员应撤离大模板下侧，以后的操作均应在上部进行。个别大块模板拆除后产生局部变形者应及时整修好。', '["大块墙模", "对拉螺栓", "作业人员", "大模板", "大块模板"]', 0.95);
