INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1727, 12, 2222, '7.6.3', '', 'active', '2026-06-03 12:34:58.212081', '2026-06-03 12:34:58.211854', 'CP-7-6-3-001', '7.6.3 拆除时应先用千斤顶顶住下部水平连接管，再拆去木楔或砖墩（或拔出钢套管连接螺栓，提起钢套管）。', '["千斤顶", "下部水平连接管", "木楔", "砖墩", "钢套管连接螺栓", "钢套管"]', 0.90);
