INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1729, 12, 2222, '7.6.3', '', 'active', '2026-06-03 12:34:58.213446', '2026-06-03 12:34:58.211854', 'CP-7-6-3-003', '若不需重复使用时，应按普通模板的方法拆除。', '["普通模板"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1740, 12, 2228, '7.7.3', '1 新浇混凝土强度应在达到承重模板拆模要求后，方准拆模。
