INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1772, 12, 2241, '8.0.11', '', 'active', '2026-06-03 12:36:13.135544', '2026-06-03 12:36:13.134399', 'CP-8-0-11-002', '施工用的临时照明和动力线应采用绝缘线和绝缘电缆线，且不得直接固定在钢模板上。', '["临时照明", "动力线", "绝缘线", "绝缘电缆线", "钢模板"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1773, 12, 2241, '8.0.11', '', 'active', '2026-06-03 12:36:13.136296', '2026-06-03 12:36:13.134399', 'CP-8-0-11-003', '夜间施工时，应有足够的照明，并应制定夜间施工的安全措施。', '["夜间施工", "照明", "安全措施"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1774, 12, 2241, '8.0.11', '', 'active', '2026-06-03 12:36:13.136928', '2026-06-03 12:36:13.134399', 'CP-8-0-11-004', '施工用临时照明和机电设备线严禁非电工乱拉乱接。', '["临时照明", "机电设备线", "非电工"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1775, 12, 2241, '8.0.11', '', 'active', '2026-06-03 12:36:13.137545', '2026-06-03 12:36:13.134399', 'CP-8-0-11-005', '同时还应经常检查线路的完好情况，严防绝缘破损漏电伤人。', '["线路", "绝缘破损"]', 0.90);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1782, 12, 2249, '8.0.19', '', 'active', '2026-06-03 12:36:29.232605', '2026-06-03 12:36:29.232387', 'CP-8-0-19-001', '当钢模板高度超过  $ 15 \, m $ 时，应安设避雷设施，避雷设施的接地电阻不得大于  $ 4 \, \Omega $。', '["钢模板", "避雷设施", "接地电阻"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1758, 12, 2235, '8.0.5', '1 立柱底部基土应回填夯实。
