INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1765, 12, 2244, '8.0.14', '', 'active', '2026-06-03 12:36:04.782768', '2026-06-03 12:36:04.782532', 'CP-8-0-14-001', '支模过程中如遇中途停歇，应将已就位模板或支架连接稳固，不得浮搁或悬空。', '["模板", "支架"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1766, 12, 2244, '8.0.14', '', 'active', '2026-06-03 12:36:04.783628', '2026-06-03 12:36:04.782532', 'CP-8-0-14-002', '拆模中途停歇时，应将已松扣或已拆松的模板、支架等拆下运走，防止构件坠落或作业人员扶空坠落伤人。', '["模板", "支架", "构件"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1776, 12, 2247, '8.0.17', '', 'active', '2026-06-03 12:36:18.716786', '2026-06-03 12:36:18.716561', 'CP-8-0-17-001', '8.0.17 寒冷地区冬期施工用钢模板时，不宜采用电热法加热混凝土，否则应采取防触电措施。', '["钢模板", "电热法", "混凝土", "防触电措施"]', 0.95);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1785, 12, 2250, '8.0.20', '', 'active', '2026-06-03 12:36:43.467741', '2026-06-03 12:36:43.467524', 'CP-8-0-20-001', '8.0.20 当遇大雨、大雾、沙尘、大雪或6级以上大风等恶劣天气时，应停止露天高处作业。', '["恶劣天气", "露天高处作业"]', 1.00);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1786, 12, 2250, '8.0.20', '', 'active', '2026-06-03 12:36:43.468504', '2026-06-03 12:36:43.467524', 'CP-8-0-20-002', '5级及以上风力时，应停止高空吊运作业。', '["风力", "高空吊运作业"]', 1.00);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1787, 12, 2250, '8.0.20', '', 'active', '2026-06-03 12:36:43.469144', '2026-06-03 12:36:43.467524', 'CP-8-0-20-003', '雨、雪停止后，应及时清除模板和地面上的积水及冰雪。', '["雨", "雪", "模板", "地面", "积水", "冰雪"]', 1.00);
INSERT INTO public.review_checkpoint (id, standard_id, clause_id, clause_no, clause_text, status, created_at, updated_at, rule_code, rule_text, object_terms, confidence) VALUES (1789, 12, 2252, '8.0.22', '1 使用后的钢模、桁架、钢楞和立柱应将粘结物清理洁净，清理时严禁采用铁锤敲击的方法。
2 清理后的钢模、桁架、钢楞、立柱，应逐块、逐榀、逐根进行检查，发现翘曲、变形、扭曲、开焊等必须修理完善。
3 清理整修好的钢模、桁架、钢楞、立柱应刷防锈漆。
4 钢模板及配件，使用后必须进行严格清理检查，已损坏断裂的应剔除，不能修复的应报废。螺栓的螺纹部分应整修上油，然后应分别按规格分类装在箱笼内备用。
5 钢模板及配件等修复后，应进行检查验收。凡检查不合格者应重新整修。待合格后方准应用，其修复后的质量标准应符合表 8.0.22 的规定。
6 钢模板由拆模现场运至仓库或维修场地时，装车不宜超出车栏杆，少量高出部分必须拴牢，零配件应分类装箱，不得散
装运输。
7 经过维修、刷油、整理合格的钢模板及配件，如需运往其他施工现场或入库，必须分类装入集装箱内，杆应成捆、配件应成箱，清点数量，入库或接收单位验收。
8 装车时，应轻搬轻放，不得相互碰撞。卸车时，严禁成捆从车上推下和拆散抛掷。
9 钢模板及配件应放入室内或敞棚内，当需露天堆放时，应装入集装箱内，底部垫高 100mm，顶面应遮盖防水篷布或塑料布，集装箱堆放高度不宜超过 2 层。
<div style="text-align: center;">表 8.0.22 钢模板及配件修复后的质量标准</div>
<table border=1 style=''margin: auto; word-wrap: break-word;''><tr><td colspan="2">项目</td><td style=''text-align: center; word-wrap: break-word;''>允许偏差（mm）</td><td colspan="2">项目</td><td style=''text-align: center; word-wrap: break-word;''>允许偏差（mm）</td></tr><tr><td rowspan="5">钢结构</td><td style=''text-align: center; word-wrap: break-word;''>板面局部不平度</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ 2.0 $</td><td rowspan="2">钢模板</td><td style=''text-align: center; word-wrap: break-word;''>板面锈皮麻面，背面粘混凝土</td><td style=''text-align: center; word-wrap: break-word;''>不允许</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>板面翘曲矢高</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ 2.0 $</td><td style=''text-align: center; word-wrap: break-word;''>孔洞破裂</td><td style=''text-align: center; word-wrap: break-word;''>不允许</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>板侧凸棱面翘曲矢高</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ 1.0 $</td><td rowspan="2">零配件</td><td style=''text-align: center; word-wrap: break-word;''>U形卡卡口残余变形</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ 1.2 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>板肋平直度</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ 2.0 $</td><td style=''text-align: center; word-wrap: break-word;''>钢楞及支柱长度方向弯曲度</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ L/1000 $</td></tr><tr><td style=''text-align: center; word-wrap: break-word;''>焊点脱焊</td><td style=''text-align: center; word-wrap: break-word;''>不允许</td><td style=''text-align: center; word-wrap: break-word;''>桁架</td><td style=''text-align: center; word-wrap: break-word;''>侧向平直度</td><td style=''text-align: center; word-wrap: break-word;''>$ ≤ 2.0 $</td></tr></table>', 'active', '2026-06-03 12:37:11.793496', '2026-06-03 12:37:11.792495', 'CP-8-0-22-002', '2 清理后的钢模、桁架、钢楞、立柱，应逐块、逐榀、逐根进行检查，发现翘曲、变形、扭曲、开焊等必须修理完善。', '["钢模", "桁架", "钢楞", "立柱"]', 0.95);
